function mountProductSlider(root,products,status){
 root.replaceChildren();root.classList.add('product-slider');
 const stage=el('div',null,'slider-stage'),image=el('img'),expand=el('button','⛶','slider-expand'),prev=el('button','‹','slider-arrow slider-prev'),next=el('button','›','slider-arrow slider-next');
 expand.type=prev.type=next.type='button';expand.setAttribute('aria-label','Expand selected product');prev.setAttribute('aria-label','Previous product');next.setAttribute('aria-label','Next product');stage.append(image,expand,prev,next);
 const details=el('div',null,'slider-details'),title=el('h3'),pack=el('p'),count=el('span',null,'slider-count');details.append(title,pack,count);const thumbs=el('div',null,'slider-thumbs');thumbs.setAttribute('aria-label','Product thumbnails');let selected=0;
 function select(index,scroll=true){selected=(index+products.length)%products.length;const p=products[selected];image.src=p.image;image.alt=p.name+' '+p.pack;title.textContent=p.name;pack.textContent=p.pack;count.textContent=String(selected+1).padStart(2,'0')+' / '+products.length;[...thumbs.children].forEach((b,i)=>{b.classList.toggle('selected',i===selected);b.setAttribute('aria-pressed',String(i===selected))});if(scroll){const b=thumbs.children[selected];thumbs.scrollTo({left:b.offsetLeft-thumbs.offsetLeft-(thumbs.clientWidth-b.clientWidth)/2,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}status.textContent=(p.company||'Grameen Danone')+' · '+p.name+' · '+(selected+1)+' of '+products.length;}
 products.forEach((p,i)=>{const b=el('button',null,'slider-thumb');b.type='button';b.setAttribute('aria-label','Show '+p.name+' '+p.pack);const img=el('img');img.src=p.image;img.alt='';img.loading='lazy';b.append(img);b.addEventListener('click',()=>select(i));thumbs.append(b)});
 prev.addEventListener('click',()=>select(selected-1));next.addEventListener('click',()=>select(selected+1));expand.addEventListener('click',()=>{lastTrigger=expand;showProduct(selected,products)});stage.tabIndex=0;stage.setAttribute('aria-label','Product image. Use left and right arrow keys to browse.');stage.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();select(selected+(e.key==='ArrowRight'?1:-1))}});let startX;stage.addEventListener('touchstart',e=>{startX=e.changedTouches[0].clientX},{passive:true});stage.addEventListener('touchend',e=>{const delta=e.changedTouches[0].clientX-startX;if(Math.abs(delta)>50)select(selected+(delta<0?1:-1))},{passive:true});root.append(stage,details,thumbs);select(0,false);
}
